          '${dropped.join(', ')}',
        ),
      );
    }
    _lastScanSkillNames = names;
    _bootSkillNames ??= names;
    _skillsScannedAt = DateTime.now();
    _skillRootsFingerprint = await _computeSkillRootsFingerprint();
  }

