  _skillsAccess = access;
  config.onSkillsAccessChanged?.call(access);
  await _reloadSkills();
  await _reloadAgents();
  io.writeln(
    'skills access: ${skillsAccessLabel(access)} — '
    '${_skills.length} skill(s) visible',
