  Future<SkillRootsFingerprint> _computeSkillRootsFingerprint() {
    final roots = defaultSkillRoots(cwd: _env.cwd, homeDir: config.homeDir);
    return computeSkillRootsFingerprint(_env, [
      ...roots.projectRoots,
