/// One wired CLI run: in-memory env + FakeShell + scripted LLM, built
/// run-varying ids and timestamps normalized away.
Future<String> _legacySessionJsonl(SpillsConfig? spills) async {
  final turns = [
    toolTurn([_bashCall('c1', 'cat big.log')]),
    textTurn('done'),
  ];
  final rig = await _rig(turns: turns, spills: spills, shellStdout: _body);
  rig.io.sendLine('go');
  await _settle(rig, 2, 'the legacy run settles');
  await _exit(rig);
  return _normalize(await _sessionJsonl(rig));
}

String _normalize(String jsonl) => jsonl
    // Bare uuid-shaped tokens anywhere: session ids in the header, the
    // agent inbox address the system prompt embeds.
    .replaceAllMapped(
      RegExp(
        r'[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-'
        r'[0-9a-fA-F]{4}-[0-9a-fA-F]{12}',
      ),
      (_) => 'UUID',
    )
    .replaceAllMapped(RegExp(r'"timestamp":"[^"]*"'), (_) => '"timestamp":"T"')
    .replaceAllMapped(RegExp(r'"timestamp":\d+'), (_) => '"timestamp":0')
    // gh-1241: the usage segment-start marker's informational `at` stamp
    // (like `timestamp`, it is wall-clock per run; the record itself is
    // identical across the three legacy configs and stays compared).
    .replaceAllMapped(RegExp(r'"at":"[^"]*"'), (_) => '"at":"T"')
    // Content hashes computed over uuid-carrying text differ per run.
    .replaceAllMapped(
      RegExp(r'"([a-zA-Z]*[hH]ash)":"[0-9a-f]{8,}"'),
      (m) => '"${m.group(1)}":"H"',
    )
    // Short per-run record ids (the uuidv7 random tail).
    .replaceAllMapped(
      RegExp(r'"(id|parentId)":"[0-9a-f]{8,}"'),
      (m) => '"${m.group(1)}":"X"',
    );

  DateTime? scannedAt,
  Set<String> midSessionNames = const {},
  bool liveRediscovery = true,
}) {
  final listed = forModel
      ? skills
            .where(
              (s) =>
                  s.modelInvocable &&
                  s.matchesTouchedPaths(touchedPaths, cwd: cwd),
            )
            .toList()
      : skills;
  if (listed.isEmpty) return '';
  String escape(String text) => text
      .replaceAll('&', '&amp;')
      .replaceAll('<', '&lt;')
      .replaceAll('>', '&gt;');
  final buffer = StringBuffer()
    ..writeln(
      'The following skills provide specialized instructions for specific '
      'tasks.',
    )
    ..writeln(
      "Use the read tool to load a skill's file when the task matches its "
      'description.',
    )
    ..writeln(
      "When a skill file references a relative path, resolve it against the "
      'skill directory (parent of SKILL.md) and use that absolute path in '
      'tool commands.',
    )
    ..writeln()
    ..writeln('<available_skills>');
  for (final skill in listed) {
    buffer
      ..writeln('  <skill>')
      ..writeln('    <name>${escape(skill.name)}</name>')
      ..writeln('    <description>${escape(skill.description)}</description>')
      ..writeln('    <location>${escape(skill.filePath)}</location>');
    if (scannedAt != null &&
        midSessionNames.contains(skill.name.toLowerCase())) {
      buffer.writeln('    <status>added mid-session (${skill.source.name})</status>');
    }
    buffer.writeln('  </skill>');
  }
  buffer.write('</available_skills>');
  if (scannedAt != null) {
    final stamp = scannedAt.toUtc().toIso8601String();
    buffer
      ..writeln()
      ..writeln(
        liveRediscovery
            ? 'skills index scanned at $stamp'
            : 'skills index scanned at $stamp — '
                'newer files are NOT reflected; /skills reload to refresh',
      );
  }
  return buffer.toString();
}

