/// gh-1440 cold-resolve, the `/skill:` miss path: re-runs discovery (full
/// provenance + manifest parse + toggle resolution through
/// [_reloadSkills]) and returns `(enabled, discovered)` post-reload. A
/// hit prints the dim refresh warning and the caller renders it exactly
/// as if indexed; a true miss keeps the caller's exact `unknown skill`
/// wording (AC4).
Future<(Skill?, Skill?)> _coldResolveSkill(String name) async {
  await _reloadSkills();
  final discovered = _skills
      .where((s) => s.name.toLowerCase() == name.toLowerCase())
      .firstOrNull;
  final enabled = _enabledSkills
      .where((s) => s.name.toLowerCase() == name.toLowerCase())
      .firstOrNull;
  if (enabled != null) {
    io.writeln(
      _style.dim(
        'skill ${enabled.name} discovered since startup — index refreshed',
      ),
    );
  }
  return (enabled, discovered);
}

/// Splits `/skill:<name> [args]` into the skill name and its args.
(String, String) _parseSkillInvocation(String rest) {
  final splitAt = rest.indexOf(RegExp(r'\s'));
  final name = (splitAt < 0 ? rest : rest.substring(0, splitAt)).trim();
  final args = splitAt < 0 ? '' : rest.substring(splitAt).trim();
  return (name, args);
}

/// `/skills [reload|access [ask|granted|denied]|import|on|off <name> [global|project]]`.
///
/// Dispatch only — each branch body lives in its own CC≤2 helper so every
/// piece stays under the CRAP ratchet even where only the line-mode paths
/// are test-covered.
Future<void> _skillsSlash(String rest) async {
  final (:sub, :args) = splitSlashArgs(rest);
  switch (sub) {
    case '':
      await _skillsListOrMenu();
    case 'reload':
      await _skillsReloadSlash();
    case 'access':
      await _skillsAccessEntry(args);
    case 'import':
      await _importThirdPartySkills();
    case 'on' || 'off':
      await _skillsToggleSlash(sub == 'on', args);

