/// Whether [text]'s frontmatter is well-formed: no `---` fence at the top,
/// or a fence whose YAML loads into a map. An OPENED fence that is never
/// closed counts as malformed — the overwhelmingly likely cause is a torn
/// write (gh-1440 E-1), and indexing the half-written tail as plain body
/// would publish a half-entry.
///
/// Skills discovery uses this to SKIP malformed files with a warning
/// instead of silently indexing them (gh-1440 AC6); the tolerant
/// [parseFrontmatterTyped] behavior is unchanged for every other caller.
bool frontmatterWellFormed(String text) {
  if (!text.startsWith('---')) return true;
  final end = text.indexOf('\n---', 3);
  if (end <= 0) return false;
  try {
    return loadYaml(text.substring(3, end)) is Map;
  } on Object {
    return false;
  }
}
}

/// Loads one skill file. Returns null when the file cannot be read — or,
/// gh-1440 AC6, when its frontmatter is malformed (skip + [onWarning];
/// a broken file must never become a half-indexed entry).
Future<Skill?> _loadSkillFile(
  ExecutionEnv env,
  String path,
  String fallbackName,
  SkillScope scope,
  SkillSource source,
  void Function(String path, String message)? onWarning,
) async {
  final text = (await env.readTextFile(path)).valueOrNull;
  if (text == null) return null;
  if (!frontmatterWellFormed(text)) {
    onWarning?.call(
      path,
      'skills: $path has malformed frontmatter — skipped '
      '(fix the yaml block and rescan)',
    );
    return null;
  }
  return skillFromText(
    text,
    filePath: path,
    fallbackName: fallbackName,
    scope: scope,
    source: source,
  );
}

