  Future<SkillRootsFingerprint> fingerprint() async {
    final roots = defaultSkillRoots(cwd: '/work', homeDir: '/home/u');
    return computeSkillRootsFingerprint(env, [
      ...roots.projectRoots,
      ...roots.userRoots,
    ]);
  }

